import { IMAGEGEN_API_ROUTE } from "@/lib/constants";
import { parseSseChunk } from "@/lib/sse";
import type { PhotoboothStyleId } from "@/lib/photobooth-styles";
import {
  DEFAULT_IMAGE_COMPLEXITY,
  supportsImageComplexity,
  type ImageComplexity,
  type ImageModelId,
} from "@/lib/image-models";

export interface HttpError<T = unknown> extends Error {
  status: number;
  payload: T;
}

const parseJson = async <T = unknown>(response: Response): Promise<T> => {
  const text = await response.text();
  if (!text) return {} as T;
  try {
    return JSON.parse(text) as T;
  } catch {
    return {} as T;
  }
};

const buildHttpError = <T>(response: Response, payload: T): HttpError<T> => {
  const detail = (payload as { error?: string | { message?: string } })?.error;
  const message =
    (typeof detail === "string" ? detail : detail?.message) ||
    response.statusText ||
    "Request failed";
  const error = new Error(message) as HttpError<T>;
  error.status = response.status;
  error.payload = payload;
  return error;
};

export type ImagegenStreamEventName =
  | "session-start"
  | "style-start"
  | "style-partial"
  | "style-final"
  | "style-error"
  | "session-error"
  | "session-complete";

export interface StreamImagegenRequest {
  model: ImageModelId;
  complexity?: ImageComplexity;
  imageDataUrl: string;
  styleIds: PhotoboothStyleId[];
  signal?: AbortSignal;
  onEvent: (
    eventName: ImagegenStreamEventName,
    payload: Record<string, unknown>
  ) => void;
}

export const streamImagegenStyles = async ({
  model,
  complexity = DEFAULT_IMAGE_COMPLEXITY,
  imageDataUrl,
  styleIds,
  signal,
  onEvent,
}: StreamImagegenRequest): Promise<void> => {
  const response = await fetch(IMAGEGEN_API_ROUTE, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      imageDataUrl,
      styleIds,
      model,
      ...(supportsImageComplexity(model) ? { complexity } : {}),
    }),
    signal,
  });

  if (!response.ok) {
    const payload = await parseJson(response);
    throw buildHttpError(response, payload);
  }

  if (!response.body) {
    throw new Error("No stream body returned by server.");
  }

  const contentType = response.headers.get("content-type") || "";
  if (!contentType.includes("text/event-stream")) {
    const payload = await parseJson<{
      results?: Array<{
        styleId?: string;
        label?: string;
        imageUrl?: string | null;
        error?: string | null;
      }>;
    }>(response);

    for (const result of payload.results ?? []) {
      if (typeof result.imageUrl === "string" && result.imageUrl) {
        onEvent("style-final", {
          styleId: result.styleId,
          label: result.label,
          imageDataUrl: result.imageUrl,
        });
      } else {
        onEvent("style-error", {
          styleId: result.styleId,
          message: result.error ?? "Style generation failed.",
        });
      }
    }

    onEvent("session-complete", {});
    return;
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  const dispatchChunk = (chunk: string): boolean => {
    const parsed = parseSseChunk(chunk);
    if (!parsed || parsed.data === "[DONE]") return false;

    let payload: Record<string, unknown>;
    try {
      payload = JSON.parse(parsed.data) as Record<string, unknown>;
    } catch {
      payload = { message: parsed.data };
    }

    if (parsed.eventName === "session-error") {
      throw new Error(
        typeof payload.message === "string"
          ? payload.message
          : "Image generation failed.",
      );
    }
    onEvent(parsed.eventName as ImagegenStreamEventName, payload);
    return parsed.eventName === "session-complete";
  };

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      buffer = buffer.replace(/\r/g, "");

      let boundary = buffer.indexOf("\n\n");
      while (boundary !== -1) {
        const chunk = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);

        if (dispatchChunk(chunk)) return;

        boundary = buffer.indexOf("\n\n");
      }
    }

    buffer += decoder.decode();
    const remaining = buffer.trim();
    if (remaining && dispatchChunk(remaining)) return;
    throw new Error("Connection closed before generation finished. Please try again.");
  } finally {
    await reader.cancel().catch(() => {});
    reader.releaseLock();
  }
};

export const IMAGE_MODELS = [
  {
    id: "gpt-image-2.6-sunburst",
    label: "gpt-image-2.6-sunburst",
  },
  {
    id: "gpt-image-2.6-flare",
    label: "gpt-image-2.6-flare",
  },
  {
    id: "gpt-image-2.5-sunburst",
    label: "gpt-image-2.5-sunburst",
  },
  {
    id: "gpt-image-2.5-flare",
    label: "gpt-image-2.5-flare",
  },
  {
    id: "gpt-image-2",
    label: "gpt-image-2",
  },
] as const;

export type ImageModelId = (typeof IMAGE_MODELS)[number]["id"];

export const DEFAULT_IMAGE_MODEL: ImageModelId = "gpt-image-2.5-flare";

export const isImageModelId = (value: unknown): value is ImageModelId =>
  IMAGE_MODELS.some((model) => model.id === value);

export const IMAGE_COMPLEXITIES = ["low", "medium", "high"] as const;

export type ImageComplexity = (typeof IMAGE_COMPLEXITIES)[number];

export const DEFAULT_IMAGE_COMPLEXITY: ImageComplexity = "high";

export const isImageComplexity = (value: unknown): value is ImageComplexity =>
  IMAGE_COMPLEXITIES.some((complexity) => complexity === value);

export const supportsImageComplexity = (model: ImageModelId): boolean =>
  model === "gpt-image-2.6-sunburst" || model === "gpt-image-2.6-flare";

export const readFileAsDataUrl = (file: File): Promise<string> =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = () => {
      if (typeof reader.result === "string") {
        resolve(reader.result);
        return;
      }
      reject(new Error("Unable to read image file."));
    };

    reader.onerror = () => reject(reader.error || new Error("File read failed."));
    reader.readAsDataURL(file);
  });

export const downloadUrl = (url: string, filename: string) => {
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.rel = "noopener noreferrer";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
};

