import { useEffect, useState } from "react";
import { findPhotoboothStyle, type PhotoboothStyleId } from "@/lib/photobooth-styles";
import { buildInitialResultCards } from "@/lib/photobooth-results";
import { loadPhotoboothRequest } from "@/lib/photobooth-session";
import type { PhotoboothRequestPayload, ResultCard } from "@/types/photobooth";
import {
  streamImagegenStyles,
  type ImagegenStreamEventName,
} from "@/services/imagegen-api";

const resolveStyleId = (value: unknown): PhotoboothStyleId | null => {
  if (typeof value !== "string") return null;
  return findPhotoboothStyle(value)?.id ?? null;
};

export const usePhotoboothResults = () => {
  const [requestData, setRequestData] = useState<PhotoboothRequestPayload | null>(null);
  const [cards, setCards] = useState<ResultCard[]>([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const retryFailedStyles = () => {
    if (loading || !requestData) return;
    const styleIds = cards
      .filter((card) => card.status === "error")
      .map((card) => card.styleId);
    if (!styleIds.length) return;
    setLoading(true);
    setRequestData({ ...requestData, styleIds });
  };

  useEffect(() => {
    const request = loadPhotoboothRequest();
    if (!request) {
      setError("No valid photo session found. Start from the home page.");
      setLoading(false);
      return;
    }

    setRequestData(request);
    setCards(buildInitialResultCards(request.styleIds));
  }, []);

  useEffect(() => {
    if (!requestData) return;

    const controller = new AbortController();
    let failureMessage = "No final image received. Retry the failed styles.";
    setCards((previousCards) => {
      const freshCards = buildInitialResultCards(requestData.styleIds);
      return previousCards.length
        ? previousCards.map((card) =>
            freshCards.find((fresh) => fresh.styleId === card.styleId) ?? card,
          )
        : freshCards;
    });
    setError("");
    setLoading(true);

    const applyEvent = (
      eventName: ImagegenStreamEventName,
      payload: Record<string, unknown>,
    ) => {
      if (controller.signal.aborted) return;
      if (eventName === "session-error") {
        const message =
          typeof payload.message === "string"
            ? payload.message
            : "Streaming failed unexpectedly.";
        setError(message);
        return;
      }

      const styleId = resolveStyleId(payload.styleId);
      if (!styleId) return;

      setCards((previousCards) =>
        previousCards.map((card) => {
          if (card.styleId !== styleId || card.status === "done") return card;

          if (eventName === "style-start") {
            return {
              ...card,
              status: "streaming",
              error: null,
            };
          }

          if (eventName === "style-partial") {
            const imageDataUrl =
              typeof payload.imageDataUrl === "string"
                ? payload.imageDataUrl
                : card.partialImageUrl;
            return {
              ...card,
              status: "streaming",
              partialImageUrl: imageDataUrl,
            };
          }

          if (eventName === "style-final") {
            const imageDataUrl =
              typeof payload.imageDataUrl === "string"
                ? payload.imageDataUrl
                : card.finalImageUrl;
            return {
              ...card,
              status: "done",
              finalImageUrl: imageDataUrl,
              partialImageUrl: imageDataUrl,
              error: null,
            };
          }

          if (eventName === "style-error") {
            return {
              ...card,
              status: "error",
              partialImageUrl: null,
              error:
                typeof payload.message === "string"
                  ? payload.message
                  : "Style generation failed.",
            };
          }

          return card;
        }),
      );
    };

    streamImagegenStyles({
      model: requestData.model,
      complexity: requestData.complexity,
      imageDataUrl: requestData.imageDataUrl,
      styleIds: requestData.styleIds,
      signal: controller.signal,
      onEvent: applyEvent,
    })
      .catch((cause) => {
        if (controller.signal.aborted) return;
        const message = cause instanceof Error ? cause.message : "";
        failureMessage =
          /network\s*error|failed to fetch|load failed|network request failed/i.test(message)
            ? "Connection lost while generating images. Check that the app is running, then retry the failed styles."
            : message || "Failed to generate styles. Retry the failed styles.";
        setError(failureMessage);
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setCards((previousCards) => previousCards.map((card) =>
            card.status === "queued" || card.status === "streaming"
              ? { ...card, status: "error", partialImageUrl: null, error: failureMessage }
              : card,
          ));
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [requestData]);

  return {
    cards,
    error,
    loading,
    retryFailedStyles,
    model: requestData?.model ?? null,
  };
};

import { useCallback, useEffect, useRef, useState } from "react";
import type { ChangeEvent, DragEvent } from "react";
import { readFileAsDataUrl } from "@/lib/browser/file-utils";
import type { SelectedImage } from "@/types/photobooth";

export const usePhotoboothCapture = () => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [cameraStream, setCameraStream] = useState<MediaStream | null>(null);
  const [selectedImage, setSelectedImage] = useState<SelectedImage | null>(null);
  const [cameraError, setCameraError] = useState("");
  const [isDragActive, setDragActive] = useState(false);

  useEffect(() => {
    return () => {
      if (!cameraStream) return;
      cameraStream.getTracks().forEach((track) => track.stop());
    };
  }, [cameraStream]);

  useEffect(() => {
    if (!cameraStream || !videoRef.current) return;

    const video = videoRef.current;
    video.srcObject = cameraStream;
    video.play().catch(() => {
      setCameraError("Unable to start camera preview.");
    });

    return () => {
      if (video.srcObject === cameraStream) {
        video.srcObject = null;
      }
    };
  }, [cameraStream]);

  const stopCamera = useCallback(() => {
    setCameraStream((currentStream) => {
      currentStream?.getTracks().forEach((track) => track.stop());
      return null;
    });
  }, []);

  const resetCapture = useCallback(() => {
    setSelectedImage(null);
    setCameraError("");
    stopCamera();
  }, [stopCamera]);

  const startCamera = useCallback(async () => {
    setCameraError("");
    setSelectedImage(null);
    stopCamera();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });
      setCameraStream(stream);
    } catch {
      setCameraError("Camera access failed. You can still upload an image.");
    }
  }, [stopCamera]);

  const takePhoto = useCallback(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    if (
      video.readyState < HTMLMediaElement.HAVE_CURRENT_DATA ||
      video.videoWidth <= 0 ||
      video.videoHeight <= 0
    ) {
      setCameraError("Camera is still getting ready.");
      return;
    }

    const width = video.videoWidth;
    const height = video.videoHeight;
    canvas.width = width;
    canvas.height = height;

    const context = canvas.getContext("2d");
    if (!context) return;

    // Keep captured output consistent with the mirrored camera preview.
    context.save();
    context.translate(width, 0);
    context.scale(-1, 1);
    context.drawImage(video, 0, 0, width, height);
    context.restore();

    setSelectedImage({ dataUrl: canvas.toDataURL("image/png"), source: "camera" });
    stopCamera();
  }, [stopCamera]);

  const openUploadPicker = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleUploadFile = useCallback(
    async (file: File) => {
      if (!file.type.startsWith("image/")) {
        setCameraError("Please drop or upload an image file.");
        return;
      }

      try {
        const dataUrl = await readFileAsDataUrl(file);
        setSelectedImage({ dataUrl, source: "upload" });
        setCameraError("");
        stopCamera();
      } catch {
        setCameraError("Unable to process uploaded image.");
      }
    },
    [stopCamera],
  );

  const onFileChange = useCallback(
    async (event: ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      await handleUploadFile(file);
      event.target.value = "";
    },
    [handleUploadFile],
  );

  const onDragOver = useCallback((event: DragEvent<HTMLElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    setDragActive(true);
  }, []);

  const onDragLeave = useCallback((event: DragEvent<HTMLElement>) => {
    event.preventDefault();
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setDragActive(false);
    }
  }, []);

  const onDrop = useCallback(
    async (event: DragEvent<HTMLElement>) => {
      event.preventDefault();
      setDragActive(false);
      const file = event.dataTransfer.files?.[0];
      if (!file) return;
      await handleUploadFile(file);
    },
    [handleUploadFile],
  );

  return {
    canvasRef,
    cameraError,
    cameraStream,
    fileInputRef,
    isDragActive,
    onDragLeave,
    onDragOver,
    onDrop,
    onFileChange,
    openUploadPicker,
    resetCapture,
    selectedImage,
    startCamera,
    takePhoto,
    videoRef,
  };
};

import { PHOTOBOOTH_SESSION_STORAGE_KEY } from "@/lib/constants";
import { normalizePhotoboothStyleIds } from "@/lib/photobooth-style-utils";
import {
  DEFAULT_IMAGE_COMPLEXITY,
  DEFAULT_IMAGE_MODEL,
  isImageComplexity,
  isImageModelId,
  supportsImageComplexity,
} from "@/lib/image-models";
import type { PhotoboothRequestPayload } from "@/types/photobooth";

const hasSessionStorage = () => typeof window !== "undefined";

export const savePhotoboothRequest = (request: PhotoboothRequestPayload) => {
  if (!hasSessionStorage()) return false;

  try {
    sessionStorage.setItem(PHOTOBOOTH_SESSION_STORAGE_KEY, JSON.stringify(request));
    return true;
  } catch {
    return false;
  }
};

export const loadPhotoboothRequest = (): PhotoboothRequestPayload | null => {
  if (!hasSessionStorage()) return null;

  try {
    const raw = sessionStorage.getItem(PHOTOBOOTH_SESSION_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as {
      model?: unknown;
      complexity?: unknown;
      imageDataUrl?: unknown;
      styleIds?: unknown;
    };

    if (
      !parsed ||
      typeof parsed.imageDataUrl !== "string" ||
      !parsed.imageDataUrl.startsWith("data:image/") ||
      !parsed.imageDataUrl.includes(";base64,")
    ) {
      return null;
    }

    const styleIds = normalizePhotoboothStyleIds(parsed.styleIds);
    if (!styleIds.length) return null;
    const model = parsed.model === undefined ? DEFAULT_IMAGE_MODEL : parsed.model;
    if (!isImageModelId(model)) return null;
    const complexity = supportsImageComplexity(model)
      ? parsed.complexity === undefined ? DEFAULT_IMAGE_COMPLEXITY : parsed.complexity
      : undefined;
    if (complexity !== undefined && !isImageComplexity(complexity)) return null;

    return {
      model,
      ...(complexity !== undefined ? { complexity } : {}),
      imageDataUrl: parsed.imageDataUrl,
      styleIds,
    };
  } catch {
    return null;
  }
};

export const clearPhotoboothRequest = () => {
  if (!hasSessionStorage()) return;
  try {
    sessionStorage.removeItem(PHOTOBOOTH_SESSION_STORAGE_KEY);
  } catch {
    // Storage can be unavailable; users should still be able to return home.
  }
};
